#pragma once
#include "plugin.hpp"
#include <cstring>

// Reusable panel parts. The graphics live in res/components and are generated by res-src/panel.py.


/** The shape with this id in an SVG, or null. */
inline NSVGshape* findShape(const std::shared_ptr<window::Svg>& svg, const char* id) {
	if (svg && svg->handle)
		for (NSVGshape* shape = svg->handle->shapes; shape; shape = shape->next)
			if (!std::strcmp(shape->id, id))
				return shape;
	return nullptr;
}

/** Fill colour of the shape with this id, so code can match colours in the artwork. */
inline NVGcolor svgFill(const std::shared_ptr<window::Svg>& svg, const char* id, NVGcolor fallback) {
	NSVGshape* shape = findShape(svg, id);
	if (!shape || shape->fill.type != NSVG_PAINT_COLOR)
		return fallback;
	uint32_t c = shape->fill.color; // nanosvg packs colours as 0xAABBGGRR
	return nvgRGBA(c & 0xff, (c >> 8) & 0xff, (c >> 16) & 0xff, c >> 24);
}


/** Widget positions, read from the hidden "components" layer of a panel SVG.

Each shape on that layer is named (its id) after the enum value of the widget that goes there:
FREQ_PARAM, OUT_LIGHT, SCREEN_WIDGET... This is the SDK's helper.py convention, so the same panel still
works with `helper.py createmodule`. Reading positions at runtime means the panel is the only place the
layout is written down: move a component in Inkscape or res-src/panel.py and the widget follows. */
struct PanelLayout {
	std::shared_ptr<window::Svg> svg;

	explicit PanelLayout(const std::string& path) : svg(window::Svg::load(path)) {}

	/** Bounding box in px, or an empty box at the origin (and a warning in the log) if the panel lacks the component. */
	math::Rect box(const char* id) const {
		NSVGshape* shape = findShape(svg, id);
		if (!shape) {
			WARN("Panel has no component named %s", id);
			return math::Rect();
		}
		return math::Rect::fromMinMax(math::Vec(shape->bounds[0], shape->bounds[1]), math::Vec(shape->bounds[2], shape->bounds[3]));
	}

	math::Vec center(const char* id) const {
		return box(id).getCenter();
	}

	math::Rect box(const std::string& id) const {
		return box(id.c_str());
	}

	math::Vec center(const std::string& id) const {
		return center(id.c_str());
	}
};


enum class Pastel { Yellow, Green, Teal, Lavender, Salmon, Cyan, Pink };

/** Large knob with a pastel cap, for a module's main parameters.

Like Rack's RoundKnob, only the pointer rotates; the cap and its highlight stay put so the lighting is
consistent. The cap is the shape with id "cap" in the background graphic, which is how a Screen readout
finds the knob's colour. */
template <Pastel P>
struct PastelKnob : RoundKnob {
	PastelKnob() {
		static const char* const colors[] = {"yellow", "green", "teal", "lavender", "salmon", "cyan", "pink"};
		setSvg(Svg::load(asset::plugin(pluginInstance, "res/components/PastelKnob.svg")));
		bg->setSvg(Svg::load(asset::plugin(pluginInstance, std::string("res/components/PastelKnob_bg-") + colors[(int) P] + ".svg")));
	}
};

/** Smaller white knob, for the soft keys beside a screen. */
struct SoftKnob : RoundKnob {
	SoftKnob() {
		setSvg(Svg::load(asset::plugin(pluginInstance, "res/components/SoftKnob.svg")));
		bg->setSvg(Svg::load(asset::plugin(pluginInstance, "res/components/SoftKnob_bg.svg")));
	}
};

/** Round momentary push button: one frame per param value, and `momentary` springs it back on release. */
struct PushButton : app::SvgSwitch {
	PushButton() {
		momentary = true;
		addFrame(Svg::load(asset::plugin(pluginInstance, "res/components/PushButton_0.svg")));
		addFrame(Svg::load(asset::plugin(pluginInstance, "res/components/PushButton_1.svg")));
	}
};

/** Rack's themed screws in the four corners. */
inline void addScrews(app::ModuleWidget* w) {
	float right = w->box.size.x - 2 * RACK_GRID_WIDTH;
	for (math::Vec pos : {math::Vec(RACK_GRID_WIDTH, 0), math::Vec(right, 0), math::Vec(RACK_GRID_WIDTH, RACK_GRID_HEIGHT - RACK_GRID_WIDTH), math::Vec(right, RACK_GRID_HEIGHT - RACK_GRID_WIDTH)})
		w->addChild(createWidget<ThemedScrew>(pos));
}


/** The colours of the OP-Z's pages of dials, as its LEDs show them, then white for the track settings. They follow the
order of the dial colours, since TE's guide doesn't list them. */
inline const NVGcolor PAGE_COLORS[] = {nvgRGB(0x3b, 0xe0, 0x7a), nvgRGB(0x3d, 0x8b, 0xff), nvgRGB(0xff, 0xc8, 0x2e), nvgRGB(0xff, 0x4d, 0x3d), nvgRGB(0xff, 0xff, 0xff)};
/** The dials' cap colours, as res-src/panelkit.py draws them. */
inline const NVGcolor DIAL_COLORS[] = {nvgRGB(0x8f, 0xcc, 0x88), nvgRGB(0x8d, 0xb2, 0xec), nvgRGB(0xf2, 0xce, 0x62), nvgRGB(0xf0, 0x94, 0x84)};
/** Held notes, on the keys and the voice LEDs. */
inline const NVGcolor NOTE_COLOR = nvgRGB(0xff, 0x7a, 0x2e);

/** One LED that takes the colour of whichever page it shows. */
struct PageLight : GrayModuleLightWidget {
	PageLight() {
		for (NVGcolor c : PAGE_COLORS)
			addBaseColor(c);
	}
};

struct NoteLight : GrayModuleLightWidget {
	NoteLight() {
		addBaseColor(NOTE_COLOR);
	}
};

/** An LED in one of the page colours: 0 to 4 for green, blue, yellow, red and white. */
template <int C>
struct ColorLight : GrayModuleLightWidget {
	ColorLight() {
		addBaseColor(PAGE_COLORS[C]);
	}
};

/** A 1.5 mm LED, between Rack's tiny and small ones. */
template <typename TBase>
struct DotLight : TBase {
	DotLight() {
		this->box.size = mm2px(math::Vec(1.5f, 1.5f));
	}
};

/** A light painted over whatever is under it, rather than added to it as Rack's LEDs are, so it shows up on light
surfaces too: the inside of a key, or a bar of colour. `off` is drawn while it's dark. */
struct SolidLight : app::ModuleLightWidget {
	float radius = 0.f;
	NVGcolor off = nvgRGBA(0, 0, 0, 0);

	void fill(const DrawArgs& args, NVGcolor c) {
		if (c.a <= 0.f)
			return;
		nvgBeginPath(args.vg);
		nvgRoundedRect(args.vg, 0, 0, box.size.x, box.size.y, radius);
		nvgFillColor(args.vg, c);
		nvgFill(args.vg);
	}
	void draw(const DrawArgs& args) override {
		fill(args, off);
	}
	void drawLayer(const DrawArgs& args, int layer) override {
		if (layer == 1)
			fill(args, color);
		Widget::drawLayer(args, layer);
	}
};

/** The bar under a page's name in the legend: faint in the page's colour, bright while that page is showing. */
struct PageBar : SolidLight {
	void setPage(int page) {
		addBaseColor(PAGE_COLORS[page]);
		off = nvgTransRGBAf(PAGE_COLORS[page], 0.25f);
	}
};

inline std::shared_ptr<window::Svg> dialCap(int color, const std::string& kind = "Dial") {
	static const char* const colors[] = {"green", "blue", "yellow", "red"};
	return Svg::load(asset::plugin(pluginInstance, "res/components/" + kind + "_bg-" + colors[color] + ".svg"));
}

/** OP-Z style dial: a big flat cap in one of the four dial colours (0 to 3: green, blue, yellow, red), with a dimple
that shows where it points. */
struct Dial : RoundKnob {
	std::string kind;

	explicit Dial(std::string kind = "Dial") : kind(kind) {
		setSvg(Svg::load(asset::plugin(pluginInstance, "res/components/" + kind + ".svg")));
	}
	Dial* color(int c) {
		bg->setSvg(dialCap(c, kind));
		return this;
	}
};

/** A dial that fills two of the Sequencer's key columns. */
struct SmallDial : Dial {
	SmallDial() : Dial("SmallDial") {}
};

/** A dial with nothing to do on this page: it looks like the others, but doesn't turn. */
struct IdleDial : widget::Widget {
	explicit IdleDial(int color, const std::string& kind = "Dial") {
		widget::SvgWidget* cap = new widget::SvgWidget;
		cap->setSvg(dialCap(color, kind));
		app::CircularShadow* shadow = new app::CircularShadow;
		shadow->box = math::Rect(math::Vec(0, cap->box.size.y * 0.1f), cap->box.size);
		box.size = cap->box.size;
		addChild(shadow);
		addChild(cap);
	}
};

/** Momentary key with a little travel. Its two frames are res/components/<name>_0.svg (up) and _1.svg (down). */
struct Key : app::SvgSwitch {
	void setGraphics(const std::string& name) {
		momentary = true;
		shadow->opacity = 0.f;
		addFrame(Svg::load(asset::plugin(pluginInstance, "res/components/" + name + "_0.svg")));
		addFrame(Svg::load(asset::plugin(pluginInstance, "res/components/" + name + "_1.svg")));
	}
};

struct PageKey : Key {
	PageKey() {
		setGraphics("PageKey");
	}
};

/** How a key was pressed, as its param's value while it's down. A param set up with configKey() can tell a plain
click from a Shift+click and a Ctrl+click (⌘+click on a Mac); one set up with configButton() reads every press as
KEY_DOWN. */
enum KeyPress { KEY_UP, KEY_DOWN, KEY_SHIFT, KEY_CTRL };

template <class TQuantity = SwitchQuantity>
TQuantity* configKey(Module* m, int paramId, std::string name = "") {
	TQuantity* q = m->configButton<TQuantity>(paramId, name);
	q->maxValue = KEY_CTRL;
	return q;
}

/** Follows a key at control rate and says what it did: PRESS as it goes down, LONG_PRESS once it has been down
`longPress` seconds, and as it's let go, CLICK, or RELEASE if the module has already handled the press. */
struct KeyGesture {
	enum Event { NONE, PRESS, LONG_PRESS, CLICK, RELEASE };
	int press = KEY_UP;     // how it was last pressed
	float held = -1.f;      // seconds down, or -1 while up
	bool handled = false;   // the press did its job already, so letting go isn't a click

	Event process(float value, float dt, float longPress = 0.4f) {
		bool down = value > 0.f;
		if (down && held < 0.f) {
			press = (int) value;
			held = 0.f;
			handled = false;
			return PRESS;
		}
		if (!down && held >= 0.f) {
			held = -1.f;
			return handled ? RELEASE : CLICK;
		}
		if (down) {
			float before = held;
			held += dt;
			if (before < longPress && held >= longPress)
				return LONG_PRESS;
		}
		return NONE;
	}

	bool down() const {
		return held >= 0.f;
	}
};

/** An OP-Z key's RGB LED: the key's symbol (a dot, a number or an icon) lit up in the colour of its three lights, red,
green and blue, with a soft glow. The unlit symbol is printed on the panel, so it follows the panel's theme; the lit
one is res/components/symbols/<name>.svg, drawn white and tinted. It lights up in a dark window, as Rack's LEDs sit in
dark bezels, so it shows over the printed symbol whatever its colour and the panel's. */
struct SymbolLight : app::ModuleLightWidget {
	std::shared_ptr<window::Svg> symbol;
	float window = mm2px(1.35f); // the dark window's radius

	/** The colour straight from the three lights, so mixes keep their hue rather than being blended by brightness. */
	void step() override {
		color = nvgRGBAf(0.f, 0.f, 0.f, 0.f);
		if (module && !module->isBypassed() && firstLightId >= 0 && firstLightId + 3 <= (int) module->lights.size()) {
			float c[3];
			for (int i = 0; i < 3; i++) {
				float b = module->lights[firstLightId + i].getBrightness();
				c[i] = std::isfinite(b) ? clamp(b, 0.f, 1.f) : 0.f;
			}
			float m = std::max({c[0], c[1], c[2]});
			if (m > 0.f)
				color = nvgRGBAf(c[0] / m, c[1] / m, c[2] / m, std::sqrt(m));
		}
		widget::Widget::step();
	}

	void drawLayer(const DrawArgs& args, int layer) override {
		if (layer == 1 && color.a > 0.f && symbol && symbol->handle) {
			math::Vec size = symbol->getSize(), c = box.size.div(2);
			nvgBeginPath(args.vg);
			nvgCircle(args.vg, c.x, c.y, window);
			nvgFillColor(args.vg, nvgTransRGBAf(settings::preferDarkPanels ? nvgRGB(0x14, 0x15, 0x16) : nvgRGB(0x3a, 0x3a, 0x3c), color.a));
			nvgFill(args.vg);
			if (settings::haloBrightness > 0.f) {
				float r = 0.7f * size.x;
				nvgBeginPath(args.vg);
				nvgCircle(args.vg, c.x, c.y, r);
				NVGcolor glow = nvgTransRGBAf(color, 0.35f * color.a * settings::haloBrightness);
				nvgFillPaint(args.vg, nvgRadialGradient(args.vg, c.x, c.y, 0.f, r, glow, nvgTransRGBAf(color, 0.f)));
				nvgFill(args.vg);
			}
			nvgSave(args.vg);
			nvgTranslate(args.vg, c.x - size.x / 2, c.y - size.y / 2);
			nvgTint(args.vg, color);
			window::svgDraw(args.vg, symbol->handle);
			nvgRestore(args.vg);
		}
		Widget::drawLayer(args, layer);
	}
};

/** An OP-Z key: round and momentary, with an RGB LED in its middle that lights up its symbol. Its ring and symbol
are printed on the panel, so it draws only how far it's pushed in. A press sets the param to how it was pressed (see
KeyPress), and it springs back on release, but not before the module has had a frame to see it. Pass
createLightParam the first of its three light ids, then place it with setRing. */
struct RoundKey : app::ParamWidget {
	SymbolLight* light = new SymbolLight;
	float radius = 0.f;     // the printed ring's
	int frames = -1;        // frames since the press, or -1 while up
	bool released = false;

	RoundKey() {
		addChild(light);
	}

	/** Puts the key over its printed ring, taking clicks a little way outside it too. */
	void setRing(math::Rect ring, const std::string& symbol) {
		box = ring.grow(mm2px(math::Vec(1.1f, 1.1f)));
		radius = ring.size.x / 2;
		light->box.size = box.size;
		light->window = 0.64f * radius;
		light->symbol = window::Svg::load(asset::plugin(pluginInstance, "res/components/symbols/" + symbol + ".svg"));
	}
	app::ModuleLightWidget* getLight() {
		return light;
	}

	void initParamQuantity() override {
		ParamWidget::initParamQuantity();
		if (engine::ParamQuantity* pq = getParamQuantity()) {
			pq->snapEnabled = true;
			pq->smoothEnabled = false;
			pq->resetEnabled = false;
			pq->randomizeEnabled = false;
		}
	}

	void onButton(const ButtonEvent& e) override {
		ParamWidget::onButton(e);
		// Rack's params take only plain clicks; take Shift and Ctrl clicks too, rather than selecting the module.
		if (e.action == GLFW_PRESS && e.button == GLFW_MOUSE_BUTTON_LEFT)
			e.consume(this);
	}
	void onDoubleClick(const DoubleClickEvent& e) override {}

	void onDragStart(const DragStartEvent& e) override {
		engine::ParamQuantity* pq = getParamQuantity();
		if (e.button != GLFW_MOUSE_BUTTON_LEFT || !pq)
			return;
		int mods = APP->window->getMods() & RACK_MOD_MASK;
		pq->setValue(mods == GLFW_MOD_SHIFT ? KEY_SHIFT : mods == RACK_MOD_CTRL ? KEY_CTRL : KEY_DOWN);
		frames = 0;
		released = false;
	}
	void onDragEnd(const DragEndEvent& e) override {
		if (e.button == GLFW_MOUSE_BUTTON_LEFT)
			released = true;
	}

	void step() override {
		if (frames >= 0 && ++frames > 1 && released) {
			if (engine::ParamQuantity* pq = getParamQuantity())
				pq->setMin();
			frames = -1;
		}
		ParamWidget::step();
	}

	void draw(const DrawArgs& args) override {
		engine::ParamQuantity* pq = getParamQuantity();
		if (pq && pq->getValue() > 0.f) {
			nvgBeginPath(args.vg);
			nvgCircle(args.vg, box.size.x / 2, box.size.y / 2, radius);
			nvgFillColor(args.vg, settings::preferDarkPanels ? nvgRGBAf(1.f, 1.f, 1.f, 0.2f) : nvgRGBAf(0.f, 0.f, 0.f, 0.18f));
			nvgFill(args.vg);
		}
		ParamWidget::draw(args);
	}
};

/** An invisible momentary button, for making printed artwork clickable. */
struct HotSpot : app::Switch {
	HotSpot() {
		momentary = true;
	}
};

